const state={role:null,token:null,page:'detect',file:null,files:[],config:null,business:null,records:[],models:[],modelActivity:[],result:null,query:'',level:'all',noticeRead:false};
const $=s=>document.querySelector(s);const content=$('#content');
const titles={detect:['INSPECTION','智能检测'],history:['RECORDS','检测记录'],review:['REVIEW','人工复核操作台'],dashboard:['MONITOR','数据监控看板'],samples:['FEEDBACK','样本回流中心'],models:['MODEL CENTER','模型版本中心'],business:['BUSINESS SETTINGS','业务配置中心'],system:['SYSTEM','模型与系统']};
const navs={user:[['detect','◫','智能检测'],['history','≡','我的记录']],staff:[['review','✓','人工复核'],['dashboard','⌁','数据看板'],['samples','↻','样本回流'],['models','⬡','模型中心'],['business','◇','业务配置'],['system','⚙','模型与系统']]};
const reviewText={approved:'复核通过',corrected:'人工修正',rejected:'复核驳回'};
const feedbackText={candidate:'待判断',included:'已加入回流',excluded:'已排除'};
const esc=value=>String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const pct=value=>value===null||value===undefined?'待导入':`${(Number(value)*100).toFixed(1)}%`;
const formatBytes=value=>{const bytes=Number(value)||0;if(bytes<1024)return `${bytes} B`;if(bytes<1024**2)return `${(bytes/1024).toFixed(1)} KB`;if(bytes<1024**3)return `${(bytes/1024**2).toFixed(1)} MB`;return `${(bytes/1024**3).toFixed(1)} GB`};

async function api(url,options={}){const request={...options,headers:{...(options.headers||{})}};if(state.token)request.headers.Authorization=`Bearer ${state.token}`;const r=await fetch(url,request);if(!r.ok)throw new Error((await r.json().catch(()=>({}))).detail||'请求失败');return r.json()}
function toast(message,type='ok'){const box=$('#toast');box.className=`toast ${type}`;box.innerHTML=`<i>${type==='ok'?'✓':'!'}</i><span>${esc(message)}</span>`;requestAnimationFrame(()=>box.classList.add('show'));clearTimeout(toast.timer);toast.timer=setTimeout(()=>box.classList.remove('show'),2800)}
async function boot(){try{state.config=(await api('/api/config')).data;document.querySelectorAll('[data-app-name]').forEach(x=>x.textContent=state.config.app.name||'包裹智检');$('#appVersion').textContent=state.config.app.version||'Desktop'}catch{}bind()}
function bind(){document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>login(b.dataset.role));$('#switchRole').onclick=logout;$('#notifyBtn').onclick=toggleNotices;$('#modal').onclick=e=>{if(e.target.id==='modal')closeModal()};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()})}
async function login(role){try{const session=(await api('/api/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({role})})).data;state.role=role;state.token=session.token;state.page=role==='user'?'detect':'review';state.noticeRead=false;$('#login').classList.add('hidden');$('#app').classList.remove('hidden');$('#identityName').textContent=session.name||(role==='user'?'使用者':'工作人员');$('#identityRole').textContent=role==='user'?'检测服务端':'质检管理端';$('#identityIcon').textContent=role==='user'?'◫':'⌁';$('#modelVersion').textContent=state.config?.model?.name||'两阶段 YOLO V1';renderNav();await refreshRecords();render()}catch(e){toast(e.message,'error')}}
async function logout(){try{if(state.token)await api('/api/session',{method:'DELETE'})}catch{}state.role=null;state.token=null;state.file=null;state.files=[];state.result=null;$('#app').classList.add('hidden');$('#login').classList.remove('hidden');$('#noticePanel').classList.add('hidden');closeModal()}
function renderNav(){const nav=$('#nav');nav.innerHTML=navs[state.role].map(([id,icon,label])=>`<button data-page="${id}" class="${id===state.page?'active':''}"><i>${icon}</i><span>${label}</span></button>`).join('');nav.querySelectorAll('button').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;renderNav();render()})}
function header(){const [eye,title]=titles[state.page];$('#pageEyebrow').textContent=eye;$('#pageTitle').textContent=title}
async function refreshRecords(){try{state.records=(await api('/api/records')).data;updateNotify()}catch{state.records=[]}}
function updateNotify(){const pending=state.role==='staff'?state.records.filter(x=>!x.reviewed_at).length:state.records.filter(x=>x.reviewed_at).length;const count=state.noticeRead?0:Math.min(pending,99);$('#notifyCount').textContent=count;$('#notifyCount').classList.toggle('hidden',count===0)}
function toggleNotices(){const box=$('#noticePanel');const pending=state.records.filter(x=>!x.reviewed_at);const high=pending.filter(x=>x.damage_level==='L3').length;box.innerHTML=state.role==='staff'?`<div class="notice-head"><strong>工作提醒</strong><button onclick="readNotices()">全部已读</button></div><div class="notice"><i class="notice-risk">${high}</i><div><strong>${pending.length} 个样本等待复核</strong><small>${high?`其中 ${high} 个 L3 高风险任务，请优先处理。`:'当前没有待处理的 L3 高风险任务。'}</small></div></div><div class="notice"><i class="notice-ok">✓</i><div><strong>模型服务正常</strong><small>${esc(state.config?.model?.name||'当前模型')} 已就绪。</small></div></div>`:`<div class="notice-head"><strong>结果提醒</strong><button onclick="readNotices()">全部已读</button></div><div class="notice"><i class="notice-ok">✓</i><div><strong>${state.records.filter(x=>x.reviewed_at).length} 条记录已有复核结果</strong><small>进入“我的记录”可以查看人工结论。</small></div></div>`;box.classList.toggle('hidden')}
window.readNotices=()=>{state.noticeRead=true;updateNotify();$('#noticePanel').classList.add('hidden');toast('消息已标记为已读')};
async function render(){header();content.innerHTML='<div class="loading-card"><span></span><p>正在读取本地数据…</p></div>';try{if(state.page!=='detect')await refreshRecords();if(state.page==='detect')renderDetect();if(state.page==='history')renderHistory();if(state.page==='review')renderReview();if(state.page==='dashboard')await renderDashboard();if(state.page==='samples')renderSamples();if(state.page==='models')await renderModels();if(state.page==='business')await renderBusiness();if(state.page==='system')await renderSystem()}catch(e){content.innerHTML=`<div class="card error-card"><h3>暂时无法读取</h3><p>${esc(e.message)}</p><button class="small-btn" onclick="render()">重新加载</button></div>`}}

function renderDetect(){content.innerHTML=`<div class="inspection-layout"><section class="card upload-card"><div class="section-title"><div><span class="step-kicker">STEP 01</span><h3>采集包裹照片</h3><div class="desc">支持单张或批量检测，每批最多 10 张。</div></div><span class="privacy-chip">仅本机处理</span></div><div class="dropzone ${state.files.length?'has-file':''}" id="dropzone"><input id="file" type="file" multiple accept="image/jpeg,image/png,image/webp"><div class="empty-upload"><div class="upload-icon">⇧</div><b>拖入图片或点击选择</b><span>可一次选择多张，单张不超过 20 MB</span></div></div><div class="upload-meta" id="uploadMeta">支持 JPG、PNG、WEBP</div><button class="primary full" id="detect" disabled><span>开始本地 AI 检测</span><b>→</b></button></section><section class="card result-card"><div class="section-title"><div><span class="step-kicker">STEP 02</span><h3>智能定损结论</h3><div class="desc">批量任务会依次处理并自动保存全部结果。</div></div><span class="model-chip">${esc(state.config?.model?.name||'YOLO V1')}</span></div><div id="result">${state.result?resultMarkup(state.result):'<div class="result-empty"><div class="scan-frame"><i></i><i></i><i></i><i></i><span>AI</span></div><strong>等待检测图片</strong><p>结果将展示标注图、置信度、风险等级与处置意见。</p></div>'}</div></section></div>`;
 const drop=$('#dropzone'),input=$('#file'),btn=$('#detect');
 const accept=fileList=>{const files=Array.from(fileList||[]).filter(file=>file.type.startsWith('image/')).slice(0,10);if(!files.length)return toast('请选择 JPG、PNG 或 WEBP 图片','error');state.files=files;state.file=files[0];const url=URL.createObjectURL(files[0]);const total=files.reduce((sum,file)=>sum+file.size,0);drop.classList.add('has-file');drop.innerHTML=`<input id="file" type="file" multiple accept="image/jpeg,image/png,image/webp"><img src="${url}" alt="待检测包裹">${files.length>1?`<span class="batch-count">共 ${files.length} 张</span>`:''}<button class="replace-btn" type="button">重新选择</button>`;$('#uploadMeta').innerHTML=`<strong>${files.length===1?esc(files[0].name):`已选择 ${files.length} 张包裹图片`}</strong><span>${(total/1024/1024).toFixed(2)} MB</span>`;btn.disabled=false;btn.querySelector('span').textContent=files.length===1?'开始本地 AI 检测':`开始批量检测（${files.length} 张）`;drop.querySelector('input').onchange=e=>accept(e.target.files);drop.querySelector('.replace-btn').onclick=()=>drop.querySelector('input').click()};
 input.onchange=()=>accept(input.files);['dragenter','dragover'].forEach(n=>drop.addEventListener(n,e=>{e.preventDefault();drop.classList.add('dragging')}));['dragleave','drop'].forEach(n=>drop.addEventListener(n,e=>{e.preventDefault();drop.classList.remove('dragging')}));drop.addEventListener('drop',e=>accept(e.dataTransfer.files));btn.onclick=detect;
}
function resultMarkup(d){const detections=d.detections||[];const top=detections.slice().sort((a,b)=>b.confidence-a.confidence)[0];return `<div class="result-visual"><img class="result-image" src="${d.result_image_url}?t=${Date.now()}" alt="AI 标注结果"><span class="result-id">任务 #${String(d.id).padStart(4,'0')}</span></div><div class="decision-head"><span class="level large ${esc(d.decision.damage_level)}">${esc(d.decision.damage_level)}</span><div><small>AI 初步结论</small><h2>${esc(d.decision.damage_type)}</h2></div><b class="confidence-ring">${top?Math.round(top.confidence*100):'--'}<small>%</small></b></div><p class="reason">${esc(d.decision.reason)}</p><div class="advice"><i>!</i><div><small>处置建议</small><strong>${esc(d.decision.recommendation)}</strong></div></div>${detections.length?`<div class="detection-list">${detections.slice(0,4).map(x=>`<span>${esc(x.damage_type)} ${esc(x.level)}<b>${Math.round(x.confidence*100)}%</b></span>`).join('')}</div>`:''}<div class="model-strip"><span><i></i>${esc(d.mode)}</span><span>${Number(d.inference_ms||0).toFixed(0)} ms</span><span>${detections.length} 个区域</span></div>`}
function batchMarkup(batch){return `<div class="batch-summary"><div><small>批量任务完成</small><strong>${batch.completed} 张成功</strong><span>${batch.failed} 张失败</span></div><div class="batch-list">${batch.results.map((r,i)=>`<button onclick="openDetail(${r.id})"><i class="${esc(r.decision.damage_level)}">${i+1}</i><span>${esc(r.filename)}</span><b>${esc(r.decision.damage_type)} · ${esc(r.decision.damage_level)}</b></button>`).join('')}${batch.errors.map(x=>`<div class="batch-error"><i>!</i><span>${esc(x.filename)}</span><b>${esc(x.message)}</b></div>`).join('')}</div></div>`}
async function detect(){const btn=$('#detect');const batch=state.files.length>1;btn.disabled=true;btn.innerHTML=`<span>${batch?`正在依次处理 ${state.files.length} 张图片…`:'正在定位包裹 · 识别损伤…'}</span><b class="spinner"></b>`;const form=new FormData();if(batch)state.files.forEach(file=>form.append('files',file));else form.append('file',state.file);try{const json=await api(batch?'/api/detect-batch':'/api/detect',{method:'POST',body:form});if(batch){if(!json.data.results.length)throw new Error('本批图片未能完成检测');state.result=json.data.results[0];$('#result').innerHTML=resultMarkup(state.result)+batchMarkup(json.data);toast(`批量检测完成：${json.data.completed} 张成功`)}else{state.result=json.data;$('#result').innerHTML=resultMarkup(state.result);toast('检测完成，结果已自动保存')}btn.innerHTML='<span>完成，重新选择图片</span><b>↻</b>';await refreshRecords()}catch(e){toast(e.message,'error');btn.innerHTML='<span>重新检测</span><b>→</b>'}finally{btn.disabled=false}}

function statusBadge(r){return r.reviewed_at?`<span class="status ${r.review_status}">${reviewText[r.review_status]||'已复核'}</span>`:'<span class="status pending">待复核</span>'}
function confidence(r){return Math.round(Math.max(...(r.detections||[]).map(x=>Number(x.confidence)||0),0)*100)}
function filteredRecords(){return state.records.filter(r=>(state.level==='all'||r.damage_level===state.level)&&(!state.query||`${r.id}${r.damage_type}${r.review_note||''}`.toLowerCase().includes(state.query.toLowerCase())))}
function recordRows(items,mode='history'){if(!items.length)return `<tr><td colspan="7"><div class="empty-state compact"><strong>没有符合条件的记录</strong><span>更换筛选条件后再试。</span></div></td></tr>`;return items.map(r=>`<tr><td><b class="record-id">#${String(r.id).padStart(4,'0')}</b></td><td>${esc(String(r.created_at).replace('T',' '))}</td><td><strong>${esc(r.damage_type)}</strong><small class="cell-meta">置信度 ${confidence(r)||'--'}%</small></td><td><span class="pill ${esc(r.damage_level)}">${esc(r.damage_level)}</span></td><td>${statusBadge(r)}</td><td>${Number(r.inference_ms||0).toFixed(0)} ms</td><td>${mode==='review'?`<button class="small-btn primary-lite" onclick="openReview(${r.id})">开始复核</button>`:`<button class="small-btn" onclick="openDetail(${r.id})">查看详情</button>`}</td></tr>`).join('')}
function listToolbar(showExport=true){return `<div class="toolbar"><label class="search"><i>⌕</i><input id="recordSearch" value="${esc(state.query)}" placeholder="搜索编号或破损类型"></label><div class="segmented"><button data-level="all" class="${state.level==='all'?'active':''}">全部</button>${['L1','L2','L3'].map(x=>`<button data-level="${x}" class="${state.level===x?'active':''}">${x}</button>`).join('')}</div>${showExport?'<a class="small-btn export" href="/api/records-export.csv">导出 CSV</a>':''}</div>`}
function bindFilters(renderFn){$('#recordSearch').oninput=e=>{state.query=e.target.value;renderFn();const next=$('#recordSearch');next.focus();next.setSelectionRange(next.value.length,next.value.length)};document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{state.level=b.dataset.level;renderFn()})}
function renderHistory(){const draw=()=>{const data=filteredRecords();content.innerHTML=`<section class="card table-card"><div class="section-title"><div><h3>我的检测记录</h3><div class="desc">AI 结论与人工复核结果自动保存在本机。</div></div><span class="total-chip">共 ${state.records.length} 条</span></div>${listToolbar()}<div class="table-wrap"><table><thead><tr><th>编号</th><th>检测时间</th><th>AI 结论</th><th>等级</th><th>复核状态</th><th>耗时</th><th>详情</th></tr></thead><tbody>${recordRows(data)}</tbody></table></div></section>`;bindFilters(draw)};draw()}
function renderReview(){const draw=()=>{const data=filteredRecords();const pending=state.records.filter(x=>!x.reviewed_at);content.innerHTML=`<div class="grid stats"><div class="card stat priority"><small>待复核任务</small><strong>${pending.length}</strong><span>实时任务队列</span></div><div class="card stat"><small>L3 高风险</small><strong>${pending.filter(x=>x.damage_level==='L3').length}</strong><span>建议优先处理</span></div><div class="card stat"><small>今日已完成</small><strong>${state.records.filter(x=>x.reviewed_at&&String(x.reviewed_at).slice(0,10)===new Date().toISOString().slice(0,10)).length}</strong><span>人工结论已留痕</span></div><div class="card stat"><small>复核完成率</small><strong>${state.records.length?Math.round(state.records.filter(x=>x.reviewed_at).length/state.records.length*100):0}%</strong><span>本机累计</span></div></div><section class="card table-card"><div class="section-title"><div><h3>人工复核队列</h3><div class="desc">打开任务对照原图和标注图，提交后自动刷新。</div></div><span class="live-chip"><i></i> 实时队列</span></div>${listToolbar(false)}<div class="table-wrap"><table><thead><tr><th>编号</th><th>检测时间</th><th>AI 结论</th><th>等级</th><th>状态</th><th>耗时</th><th>操作</th></tr></thead><tbody>${recordRows(data,'review')}</tbody></table></div></section>`;bindFilters(draw)};draw()}

function modal(markup){$('#modalBody').innerHTML=markup;$('#modal').classList.remove('hidden');document.body.classList.add('modal-open')}
window.closeModal=()=>{state.regionResizeObserver?.disconnect();$('#modal').classList.add('hidden');document.body.classList.remove('modal-open')};
function recordDetail(r,review=false){const detections=r.detections||[];return `<div class="modal-head"><div><span class="step-kicker">TASK #${String(r.id).padStart(4,'0')}</span><h2>${review?'人工复核任务':'检测记录详情'}</h2><p>${esc(String(r.created_at).replace('T',' '))} · ${esc(r.model_id||state.config?.model?.id||'当前模型')}</p></div><div class="modal-head-actions"><a href="/api/records/${r.id}/report.html" target="_blank" class="small-btn export">打印报告</a><button class="modal-close" onclick="closeModal()">×</button></div></div><div class="compare-grid"><figure><img src="/uploads/${esc(r.original_image)}" alt="包裹原图"><figcaption>原始图片</figcaption></figure><figure><img src="/results/${esc(r.result_image)}" alt="模型标注图"><figcaption>AI 标注结果</figcaption></figure></div><div class="detail-summary"><span class="level large ${esc(r.damage_level)}">${esc(r.damage_level)}</span><div><small>AI 初步结论</small><strong>${esc(r.damage_type)}</strong><p>${esc(r.reason)}</p></div><div class="confidence-block"><small>最高置信度</small><b>${confidence(r)||'--'}%</b></div></div>${detections.length?`<div class="detection-table"><div class="detection-title">识别区域明细</div>${detections.map((x,i)=>`<div><span>${i+1}</span><strong>${esc(x.damage_type)} · ${esc(x.level)}</strong><i>${Math.round(x.confidence*100)}%</i><small>面积占比 ${(Number(x.area_ratio||0)*100).toFixed(1)}%</small></div>`).join('')}</div>`:'<div class="no-detection">模型未检测到已定义的破损区域</div>'}${review?reviewForm(r):reviewConclusion(r)}`}
function reviewForm(r){return `<form id="reviewForm" class="review-form"><div class="form-title"><strong>填写人工结论</strong><span>人工结果将用于后续样本回流</span></div><div class="form-grid"><label>确认等级<select id="reviewLevel">${['L1','L2','L3'].map(x=>`<option ${x===(r.review_level||r.damage_level)?'selected':''}>${x}</option>`).join('')}</select></label><label>复核结果<select id="reviewStatus"><option value="approved">复核通过</option><option value="corrected">人工修正</option><option value="rejected">复核驳回</option></select></label></div><label>复核意见<textarea id="reviewNote" rows="3" placeholder="填写包装状态、内件风险或处置说明">${esc(r.review_note||'')}</textarea></label><div class="modal-actions"><button type="button" class="small-btn" onclick="closeModal()">取消</button><button type="submit" class="primary">提交人工复核</button></div></form>`}
function reviewConclusion(r){return `<div class="review-conclusion"><small>处置建议</small><strong>${esc(r.recommendation)}</strong>${r.reviewed_at?`<hr><small>人工复核结果</small><strong>${esc(reviewText[r.review_status]||'已复核')} · ${esc(r.review_level||r.damage_level)}</strong><span class="reviewer-line">复核人员：${esc(r.reviewer_name||'工作人员')}</span><p>${esc(r.review_note||'未填写补充意见')}</p>`:''}</div>`}
window.openDetail=async id=>{try{const r=(await api(`/api/records/${id}`)).data;modal(recordDetail(r,false))}catch(e){toast(e.message,'error')}};
window.openReview=async id=>{try{const r=(await api(`/api/records/${id}`)).data;modal(recordDetail(r,true));$('#reviewStatus').value=r.review_status||'approved';$('#reviewForm').onsubmit=async e=>{e.preventDefault();const submit=e.target.querySelector('[type=submit]');submit.disabled=true;try{await api(`/api/records/${id}/review`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({level:$('#reviewLevel').value,status:$('#reviewStatus').value,note:$('#reviewNote').value.trim()})});closeModal();await refreshRecords();render();toast('人工复核已提交，列表已刷新')}catch(err){toast(err.message,'error');submit.disabled=false}}}catch(e){toast(e.message,'error')}};

async function renderDashboard(){const d=(await api('/api/dashboard')).data;const metrics=state.config?.metrics||{};const total=Math.max(d.total,1);content.innerHTML=`<div class="dashboard-hero"><div><span class="step-kicker">MODEL OPERATIONS</span><h3>运行态势总览</h3><p>统计来源于本机真实检测与人工复核记录。</p></div><div class="hero-status"><i></i><span>本地模型在线</span><strong>${esc(state.config?.model?.name||'YOLO V1')}</strong></div></div><div class="grid stats dashboard-stats"><div class="card stat"><small>累计检测</small><strong>${d.total}</strong><span>今日新增 ${d.today_count}</span></div><div class="card stat"><small>破损检出率</small><strong>${d.damage_rate}%</strong><span>${d.damage_count} 个破损样本</span></div><div class="card stat"><small>平均推理速度</small><strong>${d.average_inference_ms?`${d.average_inference_ms.toFixed(0)} ms`:'待采集'}</strong><span>CPU 本机推理</span></div><div class="card stat"><small>存疑样本占比</small><strong>${d.uncertain_rate}%</strong><span>${d.uncertain_count} 个需关注样本</span></div></div><div class="grid dashboard-grid"><section class="card distribution"><div class="section-title"><div><h3>风险等级分布</h3><div class="desc">L3 高风险任务将进入优先复核队列</div></div><span class="total-chip">${d.total} 个样本</span></div><div class="donut-wrap"><div class="donut" style="--l1:${d.levels.L1/total*100};--l2:${(d.levels.L1+d.levels.L2)/total*100}"><div><strong>${d.damage_count}</strong><small>破损检出</small></div></div><div class="legend">${['L1','L2','L3'].map(k=>`<div><i class="dot ${k}"></i><span>${k}</span><b>${d.levels[k]}</b><small>${Math.round(d.levels[k]/total*100)}%</small></div>`).join('')}</div></div></section><section class="card metric-card"><div class="section-title"><div><h3>模型评估指标</h3><div class="desc">${esc(metrics.dataset||'待导入正式验证集')}</div></div><span class="status ${metrics.status==='verified'?'approved':'pending'}">${metrics.status==='verified'?'已验证':'待导入'}</span></div>${[['mAP@0.5',pct(metrics.map50),metrics.map50],['精确率',pct(metrics.precision),metrics.precision],['召回率',pct(metrics.recall),metrics.recall],['复核完成率',`${d.review_rate}%`,d.review_rate/100]].map(x=>`<div class="metric-row"><span>${x[0]}</span><div class="bar"><i style="width:${x[2]===null||x[2]===undefined?8:Math.max(Number(x[2])*100,3)}%"></i></div><b>${x[1]}</b></div>`).join('')}</section></div><section class="card flow-card"><div><small>样本回流能力</small><strong>${d.returned_count}</strong><span>已确认加入训练回流池</span></div><i>→</i><div><small>人工复核</small><strong>${d.reviewed}</strong><span>${d.review_rate}% 记录已留痕</span></div><i>→</i><div><small>高风险任务</small><strong>${d.high_risk_count}</strong><span>L3 样本持续监控</span></div></section>`}

function renderSamples(){const effective=x=>x.review_level||x.damage_level;const candidates=state.records.filter(x=>effective(x)==='L2'||!x.reviewed_at||x.feedback_status==='included');const included=state.records.filter(x=>x.feedback_status==='included');const eligible=candidates.filter(x=>x.reviewed_at&&(x.feedback_status||'candidate')==='candidate');content.innerHTML=`<div class="grid stats"><div class="card stat priority"><small>候选回流样本</small><strong>${candidates.filter(x=>(x.feedback_status||'candidate')==='candidate').length}</strong><span>等待工作人员判断</span></div><div class="card stat"><small>已加入回流</small><strong>${included.length}</strong><span>可导出训练候选包</span></div><div class="card stat"><small>人工已标注</small><strong>${state.records.filter(x=>x.reviewed_at).length}</strong><span>带复核结论</span></div><div class="card stat"><small>当前类别体系</small><strong>${Object.keys(state.config?.classes||{}).length}</strong><span>九类独立配置</span></div></div><section class="feedback-export-bar"><div><span class="step-kicker">TRAINING FEEDBACK</span><h3>把复核结果交给下一轮模型</h3><p>导出包包含原图、标注预览、YOLO 标签、类别配置、CSV 与完整 JSON。</p></div><div class="feedback-export-actions"><button class="small-btn" ${eligible.length?'':'disabled'} onclick="bulkIncludeFeedback()">批量加入已复核候选 · ${eligible.length}</button>${included.length?'<a class="primary dataset-download" href="/api/feedback-export.zip">导出回流训练包</a>':'<button class="primary dataset-download" disabled>暂无可导出样本</button>'}</div></section><section class="card table-card"><div class="section-title"><div><h3>样本回流池</h3><div class="desc">将有价值的存疑样本加入回流池，后续可统一导出标注和迭代模型。</div></div><span class="live-chip"><i></i> 本机持久保存</span></div><div class="table-wrap"><table><thead><tr><th>编号</th><th>预测结论</th><th>置信度</th><th>人工结果</th><th>回流状态</th><th>操作</th></tr></thead><tbody>${candidates.length?candidates.map(r=>`<tr><td><b class="record-id">#${String(r.id).padStart(4,'0')}</b></td><td>${esc(r.damage_type)} <span class="pill ${esc(r.damage_level)}">${esc(r.damage_level)}</span></td><td>${confidence(r)||'--'}%</td><td>${r.reviewed_at?`${esc(r.review_level||r.damage_level)} · ${esc(reviewText[r.review_status]||'已复核')}`:'待人工复核'}</td><td><span class="feedback ${esc(r.feedback_status||'candidate')}">${feedbackText[r.feedback_status||'candidate']}</span></td><td><button class="small-btn primary-lite" onclick="setFeedback(${r.id},'included')">加入回流</button> <button class="small-btn" onclick="setFeedback(${r.id},'excluded')">排除</button></td></tr>`).join(''):`<tr><td colspan="6"><div class="empty-state compact"><strong>暂无候选样本</strong><span>完成更多检测后，存疑样本会自动进入这里。</span></div></td></tr>`}</tbody></table></div><div class="dataset-note"><i>i</i><span>YOLO 框来自 AI 预测，已关联人工复核结论；正式训练前仍建议由标注员检查边界框。</span></div></section>`}
window.setFeedback=async(id,status)=>{try{await api(`/api/records/${id}/feedback`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({status})});await refreshRecords();render();toast(status==='included'?'样本已加入回流池':'样本已从回流池排除')}catch(e){toast(e.message,'error')}};
window.bulkIncludeFeedback=async()=>{const ids=state.records.filter(x=>x.reviewed_at&&(x.feedback_status||'candidate')==='candidate'&&(x.review_level||x.damage_level)==='L2').map(x=>x.id);if(!ids.length)return toast('当前没有已复核候选样本','error');if(!confirm(`确认将 ${ids.length} 条已复核候选样本加入回流池？`))return;try{const result=(await api('/api/feedback/bulk',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids,status:'included'})})).data;await refreshRecords();renderSamples();toast(`已批量加入 ${result.updated} 条样本`)}catch(e){toast(e.message,'error')}};

async function renderModels(){const [models,activity]=await Promise.all([api('/api/models'),api('/api/models-activity')]);state.models=models.data;state.modelActivity=activity.data;const active=state.models.find(x=>x.active);content.innerHTML=`<section class="model-center-hero"><div><span class="step-kicker">MODEL LIFECYCLE</span><h3>模型与业务解耦，版本随时可换</h3><p>候选模型先试运行，再决定是否启用；界面、历史记录、复核和定损规则无需跟着重做。</p></div><button class="model-import-btn" onclick="openModelImport()"><i>＋</i><span>导入新模型<small>两阶段 YOLO 权重</small></span></button></section>${active?`<section class="card active-model-panel"><div class="active-model-icon">AI</div><div><span class="active-label"><i></i> 当前生产版本</span><h3>${esc(active.name)}</h3><p>${esc(active.id)} · ${active.source==='imported'?'本机导入':'软件内置'} · 包裹阈值 ${Math.round(active.package_confidence*100)}% / 损伤阈值 ${Math.round(active.damage_confidence*100)}% · 输入 ${esc(active.image_size)}</p></div><div class="active-model-metrics"><div><small>mAP@0.5</small><strong>${pct(active.metrics?.map50)}</strong></div><div><small>精确率</small><strong>${pct(active.metrics?.precision)}</strong></div><div><small>召回率</small><strong>${pct(active.metrics?.recall)}</strong></div></div></section>`:''}<section class="card model-library"><div class="section-title"><div><h3>版本库</h3><div class="desc">试跑不会切换生产模型，也不会写入用户检测记录。</div></div><span class="total-chip">${state.models.length} 个版本</span></div><div class="model-version-grid">${state.models.map(modelCard).join('')}</div></section><div class="model-bottom-grid"><section class="card activity-card"><div class="section-title"><div><h3>模型操作记录</h3><div class="desc">导入、试跑、调参、切换和删除均自动留痕。</div></div><span class="total-chip">最近 ${state.modelActivity.length} 条</span></div><div class="activity-list">${state.modelActivity.length?state.modelActivity.slice(0,8).map(activityRow).join(''):'<div class="empty-activity">尚无模型操作记录</div>'}</div></section><section class="model-guide-stack"><div class="card model-guide"><b>01</b><div><strong>导入并校验</strong><span>一个包裹定位 .pt + 一个九类损伤识别 .pt</span></div></div><div class="card model-guide"><b>02</b><div><strong>试跑与调参</strong><span>用真实图片检查候选版本，不影响当前业务</span></div></div><div class="card model-guide"><b>03</b><div><strong>安全切换</strong><span>当前版本与内置版本受到删除保护</span></div></div></section></div>`}
function modelCard(m){const metrics=m.metrics||{},thresholds=m.damage_type_thresholds||{},thresholdLine=Object.keys(thresholds).length?`<p>分类阈值：撕裂 ${pct(thresholds.tear)} · 变形 ${pct(thresholds.deformation)} · 浸湿 ${pct(thresholds.wet)}</p>`:'';return `<article class="model-version ${m.active?'active':''}"><div class="model-version-head"><span class="version-source ${m.source==='imported'?'local':''}">${m.source==='imported'?'本机导入':'软件内置'}</span>${m.active?'<span class="current-tag">正在使用</span>':''}</div><h4>${esc(m.name)}</h4><code>${esc(m.id)}</code><div class="threshold-line"><span>定位 ${Math.round(m.package_confidence*100)}%</span><span>损伤 ${Math.round(m.damage_confidence*100)}%</span><span>${esc(m.image_size)} px</span></div><div class="model-mini-metrics"><span><small>mAP@0.5</small><b>${pct(metrics.map50)}</b></span><span><small>精确率</small><b>${pct(metrics.precision)}</b></span><span><small>召回率</small><b>${pct(metrics.recall)}</b></span></div><p>${metrics.status==='verified'?`${esc(metrics.dataset||'自定义验证集')} · 已验证`:'尚未登记正式评估结果'}</p>${thresholdLine}${m.release_note?`<p>${esc(m.release_note)}</p>`:''}<div class="model-version-actions"><button class="small-btn" onclick="openModelTrial('${esc(m.id)}')">试运行</button><button class="small-btn" onclick="openModelSettings('${esc(m.id)}')">参数</button><button class="small-btn" onclick="openMetrics('${esc(m.id)}')">指标</button>${m.active?'<button class="small-btn active-action" disabled>当前版本</button>':`<button class="small-btn primary-lite" onclick="activateModel('${esc(m.id)}')">启用</button>${m.source==='imported'?`<button class="small-btn danger-lite" onclick="deleteModel('${esc(m.id)}')">删除</button>`:''}`}</div></article>`}
function activityRow(item){const labels={import:['导入','activity-import'],activate:['切换','activity-activate'],metrics:['指标','activity-metrics'],settings:['调参','activity-settings'],trial:['试跑','activity-trial'],delete:['删除','activity-delete']};const meta=labels[item.action]||['操作',''];return `<div class="activity-row"><i class="${meta[1]}">${meta[0]}</i><div><strong>${esc(item.detail||item.model_id)}</strong><span>${esc(item.model_id)}</span></div><time>${esc(String(item.created_at||'').replace('T',' '))}</time></div>`}
window.activateModel=async id=>{const model=state.models.find(x=>x.id===id);if(!model)return;try{await api(`/api/models/${encodeURIComponent(id)}/activate`,{method:'POST'});state.config=(await api('/api/config')).data;$('#modelVersion').textContent=state.config.model?.name||'当前模型';await renderModels();toast(`已切换至 ${model.name}`)}catch(e){toast(e.message,'error')}};
window.openModelTrial=id=>{const model=state.models.find(x=>x.id===id);if(!model)return;modal(`<div class="modal-head"><div><span class="step-kicker">SAFE TRIAL</span><h2>候选模型试运行</h2><p>${esc(model.name)} · 不切换当前生产版本，不写入检测记录</p></div><button class="modal-close" onclick="closeModal()">×</button></div><form id="modelTrialForm" class="model-form"><label class="trial-upload"><span>选择一张真实包裹图片</span><small>支持 JPG、PNG、WEBP，单张不超过 20 MB</small><input id="trialImage" type="file" accept="image/jpeg,image/png,image/webp" required></label><div id="trialResult" class="trial-placeholder"><i>◎</i><strong>等待试运行</strong><span>结果只用于当前对照，不进入用户历史记录。</span></div><div class="modal-actions"><button type="button" class="small-btn" onclick="closeModal()">关闭</button><button type="submit" class="primary">开始试运行</button></div></form>`);$('#modelTrialForm').onsubmit=async e=>{e.preventDefault();const file=$('#trialImage').files[0],button=e.target.querySelector('[type=submit]');if(!file)return;button.disabled=true;button.textContent='正在调用候选模型…';const form=new FormData();form.append('file',file);try{const result=(await api(`/api/models/${encodeURIComponent(id)}/trial`,{method:'POST',body:form})).data;$('#trialResult').className='trial-result';$('#trialResult').innerHTML=trialResultMarkup(result);button.textContent='重新试运行';toast('候选模型试运行完成');button.disabled=false}catch(err){toast(err.message,'error');button.textContent='重新试运行';button.disabled=false}}};
function trialResultMarkup(r){const top=(r.detections||[]).slice().sort((a,b)=>b.confidence-a.confidence)[0];return `<img src="${r.result_image_url}?t=${Date.now()}" alt="候选模型标注结果"><div class="trial-decision"><span class="level ${esc(r.decision.damage_level)}">${esc(r.decision.damage_level)}</span><div><small>试运行结论</small><strong>${esc(r.decision.damage_type)}</strong><p>${esc(r.decision.reason)}</p></div><b>${top?Math.round(top.confidence*100):'--'}%</b></div><div class="model-strip"><span><i></i>${esc(r.mode)}</span><span>${Number(r.inference_ms||0).toFixed(0)} ms</span><span>${(r.detections||[]).length} 个区域</span></div>`}
window.openModelSettings=id=>{const model=state.models.find(x=>x.id===id);if(!model)return;modal(`<div class="modal-head"><div><span class="step-kicker">INFERENCE SETTINGS</span><h2>模型推理参数</h2><p>${esc(model.name)} · 参数只属于当前模型版本</p></div><button class="modal-close" onclick="closeModal()">×</button></div><form id="modelSettingsForm" class="model-form"><div class="metric-input-grid"><label>包裹定位阈值（%）<input id="packageConfidence" type="number" min="1" max="95" step="1" value="${Math.round(model.package_confidence*100)}" required></label><label>损伤识别阈值（%）<input id="damageConfidence" type="number" min="1" max="95" step="1" value="${Math.round(model.damage_confidence*100)}" required></label><label>模型输入尺寸<select id="modelImageSize">${[320,416,512,640,768,960,1280].map(size=>`<option value="${size}" ${Number(model.image_size)===size?'selected':''}>${size} × ${size}</option>`).join('')}</select></label></div><div class="settings-explain"><div><i>低</i><span><strong>降低阈值</strong>更容易检出细小破损，但存疑样本可能增加。</span></div><div><i>高</i><span><strong>提高阈值</strong>结果更保守，但可能漏掉不明显破损。</span></div></div><div class="modal-actions"><button type="button" class="small-btn" onclick="closeModal()">取消</button><button type="submit" class="primary">保存独立参数</button></div></form>`);$('#modelSettingsForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{await api(`/api/models/${encodeURIComponent(id)}/settings`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({package_confidence:Number($('#packageConfidence').value)/100,damage_confidence:Number($('#damageConfidence').value)/100,image_size:Number($('#modelImageSize').value)})});state.config=(await api('/api/config')).data;closeModal();await renderModels();toast('模型推理参数已保存')}catch(err){toast(err.message,'error');button.disabled=false}}};
window.deleteModel=async id=>{const model=state.models.find(x=>x.id===id);if(!model||!confirm(`确定删除“${model.name}”吗？\n\n模型权重和对应评估指标将从本机移除，此操作不可撤销。`))return;try{await api(`/api/models/${encodeURIComponent(id)}`,{method:'DELETE'});await renderModels();toast('模型版本已删除')}catch(e){toast(e.message,'error')}};
window.openModelImport=()=>{modal(`<div class="modal-head"><div><span class="step-kicker">IMPORT MODEL</span><h2>导入两阶段 YOLO 模型</h2><p>权重保存在软件外部数据目录，升级程序不会覆盖。</p></div><button class="modal-close" onclick="closeModal()">×</button></div><form id="modelImportForm" class="model-form"><div class="model-form-grid"><label>模型编号<small>3–40 位英文、数字、点、横线或下划线</small><input id="newModelId" required minlength="3" maxlength="40" pattern="[A-Za-z0-9][A-Za-z0-9._-]{2,39}" placeholder="例如 nine-class-v2"></label><label>展示名称<small>工作人员和检测记录中显示的版本名</small><input id="newModelName" required maxlength="60" placeholder="例如 九类破损模型 V2"></label></div><div class="weight-upload-grid"><label><span>阶段一 · 包裹定位模型</span><small>上传 Ultralytics YOLO .pt 权重</small><input id="packageWeights" type="file" accept=".pt" required></label><label><span>阶段二 · 九类损伤模型</span><small>必须包含恰好 9 个输出类别</small><input id="damageWeights" type="file" accept=".pt" required></label></div><div class="import-note"><i>✓</i><span>导入时会校验两个模型并保存为候选版本，不会自动替换当前生产模型。</span></div><div class="modal-actions"><button type="button" class="small-btn" onclick="closeModal()">取消</button><button type="submit" class="primary">校验并导入</button></div></form>`);$('#modelImportForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');const packageFile=$('#packageWeights').files[0],damageFile=$('#damageWeights').files[0];if(!packageFile||!damageFile)return toast('请选择两个 .pt 模型文件','error');button.disabled=true;button.textContent='正在读取并校验模型…';const form=new FormData();form.append('model_id',$('#newModelId').value.trim());form.append('model_name',$('#newModelName').value.trim());form.append('package_weights',packageFile);form.append('damage_weights',damageFile);try{await api('/api/models/import',{method:'POST',body:form});state.config=(await api('/api/config')).data;$('#modelVersion').textContent=state.config.model?.name||'当前模型';closeModal();await renderModels();toast('候选模型已导入，可先试运行再启用')}catch(err){toast(err.message,'error');button.disabled=false;button.textContent='校验并导入'}}};
window.openMetrics=id=>{const model=state.models.find(x=>x.id===id);if(!model)return;const metrics=model.metrics||{};const number=value=>value===null||value===undefined?'':(Number(value)*100).toFixed(1);modal(`<div class="modal-head"><div><span class="step-kicker">MODEL EVALUATION</span><h2>登记评估指标</h2><p>${esc(model.name)} · ${esc(model.id)}</p></div><button class="modal-close" onclick="closeModal()">×</button></div><form id="metricsForm" class="model-form"><div class="metric-input-grid"><label>mAP@0.5（%）<input id="metricMap" type="number" min="0" max="100" step="0.1" value="${number(metrics.map50)}" required></label><label>精确率（%）<input id="metricPrecision" type="number" min="0" max="100" step="0.1" value="${number(metrics.precision)}" required></label><label>召回率（%）<input id="metricRecall" type="number" min="0" max="100" step="0.1" value="${number(metrics.recall)}" required></label></div><label>验证数据集名称<input id="metricDataset" required maxlength="100" value="${esc(metrics.dataset==='待导入正式验证集评估结果'?'':metrics.dataset||'')}" placeholder="例如 九类破损验证集 2026-Q3"></label><div class="import-note"><i>i</i><span>这里登记的是离线验证集结果，不会用实时业务数据伪装模型精度。</span></div><div class="modal-actions"><button type="button" class="small-btn" onclick="closeModal()">取消</button><button type="submit" class="primary">保存评估结果</button></div></form>`);$('#metricsForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{await api(`/api/models/${encodeURIComponent(id)}/metrics`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({map50:Number($('#metricMap').value)/100,precision:Number($('#metricPrecision').value)/100,recall:Number($('#metricRecall').value)/100,dataset:$('#metricDataset').value.trim()})});state.config=(await api('/api/config')).data;closeModal();await renderModels();toast('模型评估指标已保存')}catch(err){toast(err.message,'error');button.disabled=false}}};

async function refreshBusiness(){state.config=(await api('/api/config')).data;state.business=(await api('/api/business-settings')).data;document.querySelectorAll('[data-app-name]').forEach(x=>x.textContent=state.config.app.name);const account=state.config.accounts.find(x=>x.role===state.role);if(account)$('#identityName').textContent=account.name}
async function renderBusiness(){state.business=(await api('/api/business-settings')).data;const b=state.business,classes=Object.entries(b.classes||{}),rules=b.rules||{};content.innerHTML=`<section class="business-hero"><div><span class="step-kicker">NO-CODE CONFIGURATION</span><h3>以后补名称和正式规则，不需要重新开发</h3><p>这里保存的内容独立于程序安装包，升级桌面版后仍然保留。</p></div><div class="business-summary"><span><b>${classes.length}</b> 个模型类别</span><span><b>3</b> 级处置规则</span></div></section><div class="business-top-grid"><form id="brandingForm" class="card config-card"><div class="section-title"><div><h3>软件名称</h3><div class="desc">最终名称确定后在这里替换。</div></div><span class="config-icon">Aa</span></div><label>产品名称<input id="brandName" maxlength="40" required value="${esc(b.app?.name||'')}"></label><label>产品说明<input id="brandSubtitle" maxlength="80" required value="${esc(b.app?.subtitle||'')}"></label><button class="primary" type="submit">保存名称</button></form><form id="accountsForm" class="card config-card"><div class="section-title"><div><h3>身份显示名称</h3><div class="desc">登录角色与权限范围保持不变。</div></div><span class="config-icon">ID</span></div><label>使用者名称<input id="userAccountName" maxlength="40" required value="${esc((b.accounts||[]).find(x=>x.role==='user')?.name||'')}"></label><label>工作人员名称<input id="staffAccountName" maxlength="40" required value="${esc((b.accounts||[]).find(x=>x.role==='staff')?.name||'')}"></label><button class="primary" type="submit">保存身份</button></form></div><form id="rulesForm" class="card config-card rules-config-card"><div class="section-title"><div><h3>L1–L3 正式处置规则</h3><div class="desc">检测结果、复核详情和打印报告将统一使用这里的业务口径。</div></div><span class="total-chip">独立配置</span></div><div class="rule-edit-grid">${['L1','L2','L3'].map(level=>`<div class="rule-edit ${level}"><span class="level ${level}">${level}</span><label>等级名称<input data-rule-label="${level}" maxlength="30" required value="${esc(rules[level]?.label||'')}"></label><label>处置建议<textarea data-rule-copy="${level}" maxlength="200" rows="3" required>${esc(rules[level]?.recommendation||'')}</textarea></label></div>`).join('')}</div><div class="form-save-row"><span>保存后立即用于下一条检测结果。</span><button class="primary" type="submit">保存处置规则</button></div></form><form id="classesForm" class="card config-card classes-config-card"><div class="section-title"><div><h3>九类模型输出映射</h3><div class="desc">输出名必须与损伤模型内部类别一致；业务类型和等级可以独立调整。</div></div><span class="total-chip">必须恰好 9 类</span></div><div class="class-edit-table"><div class="class-edit-head"><span>序号</span><span>模型输出名称</span><span>业务显示类型</span><span>损伤等级</span></div>${classes.map(([key,value],i)=>`<div class="class-edit-row"><b>${String(i+1).padStart(2,'0')}</b><input data-class-output="${i}" maxlength="80" required value="${esc(key)}"><input data-class-type="${i}" maxlength="30" required value="${esc(value.type)}"><select data-class-level="${i}">${['L1','L2','L3'].map(level=>`<option ${value.level===level?'selected':''}>${level}</option>`).join('')}</select></div>`).join('')}</div><div class="form-save-row"><span>当前内置模型输出：tear、deformation、wet 各三个等级。</span><button class="primary" type="submit">保存九类映射</button></div></form>`;bindBusinessForms(classes.length)}
function bindBusinessForms(classCount){$('#brandingForm').onsubmit=async e=>{e.preventDefault();await saveBusinessForm(e,'/api/business-settings/branding',{name:$('#brandName').value,subtitle:$('#brandSubtitle').value},'软件名称已更新')};$('#accountsForm').onsubmit=async e=>{e.preventDefault();await saveBusinessForm(e,'/api/business-settings/accounts',{user_name:$('#userAccountName').value,staff_name:$('#staffAccountName').value},'身份显示名称已更新')};$('#rulesForm').onsubmit=async e=>{e.preventDefault();const items={};['L1','L2','L3'].forEach(level=>items[level]={label:$(`[data-rule-label="${level}"]`).value,recommendation:$(`[data-rule-copy="${level}"]`).value});await saveBusinessForm(e,'/api/business-settings/rules',{items},'L1–L3 处置规则已更新')};$('#classesForm').onsubmit=async e=>{e.preventDefault();const items=Array.from({length:classCount},(_,i)=>({output_name:$(`[data-class-output="${i}"]`).value,damage_type:$(`[data-class-type="${i}"]`).value,level:$(`[data-class-level="${i}"]`).value}));await saveBusinessForm(e,'/api/business-settings/classes',{items},'九类模型映射已更新')}}
async function saveBusinessForm(event,url,body,message){const button=event.target.querySelector('[type=submit]');button.disabled=true;try{await api(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});await refreshBusiness();toast(message);await renderBusiness()}catch(e){toast(e.message,'error');button.disabled=false}}

async function renderSystem(){const c=state.config||{},m=c.model||{},classes=c.classes||{},rules=c.rules||{};const health=(await api('/api/model-health')).data;const healthy=health.status==='ready';content.innerHTML=`<div class="system-grid"><section class="card model-overview"><div class="model-badge">AI</div><div><span class="step-kicker">ACTIVE MODEL</span><h3>${esc(m.name||'当前模型')}</h3><p>${esc(m.id||'未配置')} · ${esc(m.adapter||'适配器未配置')}</p></div><span class="live-chip ${healthy?'':'warning'}"><i></i> ${healthy?'全部组件就绪':'需要检查'}</span></section><section class="card"><div class="section-title"><div><h3>运行健康</h3><div class="desc">${esc(health.engine)}</div></div><a class="small-btn export" href="/api/backup">导出完整备份</a></div><div class="kv-grid health-kv"><div><small>包裹模型</small><strong>${health.checks.package_model?'已就绪':'缺失'}</strong></div><div><small>损伤模型</small><strong>${health.checks.damage_model?'已就绪':'缺失'}</strong></div><div><small>数据库完整性</small><strong>${health.checks.database_integrity?'正常':'异常'}</strong></div><div><small>九类映射</small><strong>${health.checks.class_mapping?'完整':'需补充'}</strong></div></div></section></div><section class="card maintenance-card"><div class="maintenance-copy"><span class="step-kicker">LOCAL DATA HEALTH</span><h3>本机数据自检</h3><p>自动检查数据库、磁盘容量和失去记录关联的图片缓存。</p></div><div class="maintenance-stats"><div><small>业务记录</small><strong>${health.database.record_count}</strong></div><div><small>数据占用</small><strong>${formatBytes(health.storage_bytes)}</strong></div><div><small>磁盘可用</small><strong>${formatBytes(health.disk_free_bytes)}</strong></div><div class="${health.orphan_count?'attention':''}"><small>孤立文件</small><strong>${health.orphan_count}</strong></div></div><button class="small-btn ${health.orphan_count?'danger-lite':''}" ${health.orphan_count?'':'disabled'} onclick="cleanupOrphans()">${health.orphan_count?'检查并清理':'无需清理'}</button></section>${health.missing_classes?.length?`<section class="mapping-warning"><i>!</i><div><strong>当前模型有 ${health.missing_classes.length} 个输出尚未映射</strong><span>${health.missing_classes.map(esc).join('、')}</span></div><button class="small-btn" onclick="state.page='business';renderNav();render()">前往配置</button></section>`:''}<div class="grid cols-2 system-lower"><section class="card"><div class="section-title"><div><h3>九类损伤映射</h3><div class="desc">模型输出名称与业务中文名称解耦</div></div><span class="total-chip">${health.mapped_class_count}/${health.class_count||Object.keys(classes).length}</span></div><div class="class-grid">${Object.entries(classes).map(([key,value])=>`<div><code>${esc(key)}</code><span>${esc(value.type)}</span><b class="pill ${esc(value.level)}">${esc(value.level)}</b></div>`).join('')}</div></section><section class="card"><div class="section-title"><div><h3>L1–L3 处置规则</h3><div class="desc">后期确定正式规则后，只需更新配置</div></div><span class="total-chip">独立配置</span></div><div class="rule-list">${Object.entries(rules).map(([level,value])=>`<div><span class="level ${esc(level)}">${esc(level)}</span><div><strong>${esc(value.label)}</strong><p>${esc(value.recommendation)}</p></div></div>`).join('')}</div></section></div><section class="card architecture-card"><div><span>01</span><strong>桌面界面</strong><small>登录、批量检测、复核</small></div><i>→</i><div><span>02</span><strong>业务接口</strong><small>权限、记录、备份</small></div><i>→</i><div><span>03</span><strong>模型适配层</strong><small>试跑、切换、推理</small></div><i>→</i><div><span>04</span><strong>数据闭环</strong><small>复核、回流、再训练</small></div></section>`}
window.cleanupOrphans=async()=>{if(!confirm('确定清理孤立文件吗？\n\n只会删除没有任何检测记录引用的上传图和结果图，不影响正常记录。'))return;try{const result=(await api('/api/maintenance/cleanup-orphans',{method:'POST'})).data;await renderSystem();toast(`已清理 ${result.removed_count} 个文件，释放 ${formatBytes(result.freed_bytes)}`)}catch(e){toast(e.message,'error')}};

const baseActivityRow=activityRow;
activityRow=function(item){if(item.action!=='compare')return baseActivityRow(item);return `<div class="activity-row"><i class="activity-compare">对比</i><div><strong>${esc(item.detail||item.model_id)}</strong><span>${esc(item.model_id)}</span></div><time>${esc(String(item.created_at||'').replace('T',' '))}</time></div>`};
const baseRenderModels=renderModels;
renderModels=async function(){await baseRenderModels();const hero=document.querySelector('.model-center-hero'),importButton=hero?.querySelector('.model-import-btn');if(!hero||!importButton)return;const actions=document.createElement('div');actions.className='model-hero-actions';const compare=document.createElement('button');compare.className='model-compare-btn';compare.innerHTML='<i>A/B</i><span>对比评测<small>1–5 张图不切换生产版</small></span>';compare.onclick=openModelCompare;hero.insertBefore(actions,importButton);actions.append(compare,importButton)};

window.openModelCompare=()=>{if(state.models.length<2){modal(`<div class="modal-head"><div><span class="step-kicker">MODEL A/B TEST</span><h2>需要两个模型版本</h2><p>当前版本库只有 ${state.models.length} 个模型，请先导入一个候选模型。</p></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="compare-empty"><i>A/B</i><strong>不需要启用候选版本</strong><span>导入后即可对比，整个评测不会改变当前生产模型。</span></div><div class="modal-actions"><button class="small-btn" onclick="closeModal()">知道了</button><button class="primary" onclick="closeModal();openModelImport()">导入候选模型</button></div>`);return}const options=state.models.map((m,i)=>`<option value="${esc(m.id)}" ${i===0?'selected':''}>${esc(m.name)}${m.active?' · 当前版':''}</option>`).join('');const optionsB=state.models.map((m,i)=>`<option value="${esc(m.id)}" ${i===1?'selected':''}>${esc(m.name)}${m.active?' · 当前版':''}</option>`).join('');modal(`<div class="modal-head"><div><span class="step-kicker">MODEL A/B TEST</span><h2>模型对比评测</h2><p>用同一组图片比较两个版本，不写入检测记录，不切换生产模型。</p></div><button class="modal-close" onclick="closeModal()">×</button></div><form id="modelCompareForm" class="model-form"><div class="compare-select-grid"><label>模型 A<select id="compareModelA">${options}</select></label><span>VS</span><label>模型 B<select id="compareModelB">${optionsB}</select></label></div><label class="trial-upload"><span>选择 1–5 张真实测试图片</span><small>支持 JPG、PNG、WEBP，会对每张图给出双模型结论。</small><input id="compareImages" type="file" multiple accept="image/jpeg,image/png,image/webp" required></label><div id="modelCompareResult" class="trial-placeholder"><i>A/B</i><strong>等待对比评测</strong><span>平均推理时间、检出数、L3 数量与逐图结论将集中展示。</span></div><div class="modal-actions"><button type="button" class="small-btn" onclick="closeModal()">关闭</button><button type="submit" class="primary">开始 A/B 对比</button></div></form>`);$('#modelCompareForm').onsubmit=async e=>{e.preventDefault();const files=[...$('#compareImages').files],button=e.target.querySelector('[type=submit]');if(!files.length||files.length>5)return toast('请选择 1–5 张图片','error');if($('#compareModelA').value===$('#compareModelB').value)return toast('请选择两个不同的模型','error');button.disabled=true;button.textContent='两个模型正在依次评测…';const form=new FormData();form.append('model_a',$('#compareModelA').value);form.append('model_b',$('#compareModelB').value);files.forEach(file=>form.append('files',file));try{const result=(await api('/api/models/compare',{method:'POST',body:form})).data;$('#modelCompareResult').className='model-compare-results';$('#modelCompareResult').innerHTML=modelCompareMarkup(result);button.textContent='重新对比';button.disabled=false;toast(`对比完成：${result.agreement_count}/${result.sample_count} 张结论一致`)}catch(err){toast(err.message,'error');button.textContent='重新对比';button.disabled=false}}};
function compareDecisionMarkup(result,model){const top=(result.detections||[]).reduce((best,item)=>item.confidence>(best?.confidence||0)?item:best,null);return `<figure><div class="compare-image-head"><span>${esc(model.name)}</span><b>${Number(result.inference_ms||0).toFixed(0)} ms</b></div><img src="${result.result_image_url}?t=${Date.now()}" alt="${esc(model.name)} 标注结果"><figcaption><span class="level ${esc(result.decision.damage_level)}">${esc(result.decision.damage_level)}</span><div><strong>${esc(result.decision.damage_type)}</strong><small>${(result.detections||[]).length} 个区域 · 最高 ${top?Math.round(top.confidence*100)+'%':'--'}</small></div></figcaption></figure>`}
function modelCompareMarkup(data){const [a,b]=data.models;return `<div class="compare-summary"><div><small>结论一致率</small><strong>${Math.round(data.agreement_rate*100)}%</strong><span>${data.agreement_count}/${data.sample_count} 张</span></div><div><small>${esc(a.name)} 平均速度</small><strong>${Number(a.average_inference_ms).toFixed(0)} ms</strong><span>${a.total_detections} 区域 · ${a.high_risk_count} 个 L3</span></div><div><small>${esc(b.name)} 平均速度</small><strong>${Number(b.average_inference_ms).toFixed(0)} ms</strong><span>${b.total_detections} 区域 · ${b.high_risk_count} 个 L3</span></div><div class="production-safe"><small>生产模型</small><strong>${data.active_unchanged?'未切换':'需检查'}</strong><span>${esc(data.active_model_after)}</span></div></div><div class="comparison-list">${data.comparisons.map(item=>`<section><header><strong>${esc(item.filename)}</strong><span class="${item.agreement?'agree':'differ'}">${item.agreement?'结论一致':'结论有差异'}</span></header><div class="comparison-pair">${compareDecisionMarkup(item.a,a)}${compareDecisionMarkup(item.b,b)}</div></section>`).join('')}</div>`}
state.recordPageIndex=0;state.recordPageSize=20;state.recordPageRequest=0;
const pagedToolbar=showExport=>`<div class="toolbar"><label class="search"><i>⌕</i><input id="recordSearch" value="${esc(state.query)}" placeholder="搜索编号、破损类型、备注或复核人"></label><div class="segmented"><button data-level="all" class="${state.level==='all'?'active':''}">全部</button>${['L1','L2','L3'].map(x=>`<button data-level="${x}" class="${state.level===x?'active':''}">${x}</button>`).join('')}</div>${showExport?'<a class="small-btn export" href="/api/records-export.csv">导出 CSV</a>':''}</div>`;
function paginationMarkup(page){const current=Math.floor(page.offset/page.limit)+1,totalPages=Math.max(1,Math.ceil(page.total/page.limit)),start=page.total?page.offset+1:0,end=Math.min(page.offset+page.items.length,page.total);return `<div class="pagination"><span>显示 ${start}–${end} 条，共 ${page.total} 条</span><div><button class="small-btn" data-page-step="-1" ${current<=1?'disabled':''}>上一页</button><b>${current} / ${totalPages}</b><button class="small-btn" data-page-step="1" ${current>=totalPages?'disabled':''}>下一页</button></div></div>`}
async function renderPagedRecords(mode){const expected=mode==='review'?'review':'history',request=++state.recordPageRequest;content.innerHTML='<div class="loading-card"><span></span><p>正在读取分页记录…</p></div>';const params=new URLSearchParams({limit:String(state.recordPageSize),offset:String(state.recordPageIndex*state.recordPageSize),query:state.query,level:state.level});try{const page=(await api(`/api/records-page?${params}`)).data;if(request!==state.recordPageRequest||state.page!==expected)return;if(page.total&&page.offset>=page.total){state.recordPageIndex=Math.max(0,Math.ceil(page.total/page.limit)-1);return renderPagedRecords(mode)}const summary=page.summary||{};if(mode==='history'){content.innerHTML=`<section class="card table-card"><div class="section-title"><div><h3>我的检测记录</h3><div class="desc">AI 结论与人工复核结果自动保存在本机，长期数据按页读取。</div></div><span class="total-chip">共 ${page.total} 条</span></div>${pagedToolbar(true)}<div class="table-wrap"><table><thead><tr><th>编号</th><th>检测时间</th><th>AI 结论</th><th>等级</th><th>复核状态</th><th>耗时</th><th>详情</th></tr></thead><tbody>${recordRows(page.items)}</tbody></table></div>${paginationMarkup(page)}</section>`}else{content.innerHTML=`<div class="grid stats"><div class="card stat priority"><small>待复核任务</small><strong>${summary.pending_count||0}</strong><span>全部实时任务队列</span></div><div class="card stat"><small>L3 待复核</small><strong>${summary.pending_high_risk_count||0}</strong><span>建议优先处理</span></div><div class="card stat"><small>今日已完成</small><strong>${summary.reviewed_today||0}</strong><span>人工结论已留痕</span></div><div class="card stat"><small>复核完成率</small><strong>${summary.review_rate||0}%</strong><span>全部 ${summary.total||0} 条记录</span></div></div><section class="card table-card"><div class="section-title"><div><h3>人工复核队列</h3><div class="desc">服务端搜索与分页，数据增长后仍能快速打开。</div></div><span class="live-chip"><i></i> 实时队列</span></div>${pagedToolbar(false)}<div class="table-wrap"><table><thead><tr><th>编号</th><th>检测时间</th><th>AI 结论</th><th>等级</th><th>状态</th><th>耗时</th><th>操作</th></tr></thead><tbody>${recordRows(page.items,'review')}</tbody></table></div>${paginationMarkup(page)}</section>`}bindPagedRecords(mode)}catch(error){if(request===state.recordPageRequest)content.innerHTML=`<div class="card error-card"><h3>记录读取失败</h3><p>${esc(error.message)}</p><button class="small-btn" onclick="renderPagedRecords('${mode}')">重新加载</button></div>`}}
function bindPagedRecords(mode){const search=$('#recordSearch');let timer;search.oninput=e=>{state.query=e.target.value;state.recordPageIndex=0;clearTimeout(timer);timer=setTimeout(()=>renderPagedRecords(mode),280)};document.querySelectorAll('[data-level]').forEach(button=>button.onclick=()=>{state.level=button.dataset.level;state.recordPageIndex=0;renderPagedRecords(mode)});document.querySelectorAll('[data-page-step]').forEach(button=>button.onclick=()=>{state.recordPageIndex=Math.max(0,state.recordPageIndex+Number(button.dataset.pageStep));renderPagedRecords(mode)})}
renderHistory=function(){renderPagedRecords('history')};renderReview=function(){renderPagedRecords('review')};
const baseRenderSystem=renderSystem;
renderSystem=async function(){await baseRenderSystem();const first=document.querySelector('.system-grid');if(!first)return;first.insertAdjacentHTML('afterend','<section class="resilience-strip"><div><i>✓</i><span><strong>真实图片校验</strong><small>拦截损坏文件与超大像素图</small></span></div><div><i>✓</i><span><strong>并发推理保护</strong><small>避免多任务切换模型时互相干扰</small></span></div><div><i>✓</i><span><strong>失败自动回滚</strong><small>不保留不完整图片和业务记录</small></span></div></section>')};
const systemWithResilience=renderSystem;
renderSystem=async function(){await systemWithResilience();const download=document.querySelector('a[href="/api/backup"]');if(!download)return;download.insertAdjacentHTML('beforebegin','<button class="small-btn restore-backup-btn" onclick="openBackupRestore()">恢复备份</button>')};
window.openBackupRestore=()=>{modal(`<div class="modal-head"><div><span class="step-kicker">SAFE DATA RESTORE</span><h2>恢复完整备份</h2><p>先校验备份和数据库，通过后才允许恢复。</p></div><button class="modal-close" onclick="closeModal()">×</button></div><form id="backupRestoreForm" class="model-form"><label class="trial-upload"><span>选择本软件导出的 .zip 备份包</span><small>恢复会替换当前记录、图片、模型和业务配置。</small><input id="backupRestoreFile" type="file" accept=".zip,application/zip" required></label><div id="backupInspection" class="backup-inspection pending"><i>…</i><div><strong>等待选择备份包</strong><span>不会仅凭文件名恢复，系统会检查内部清单和 SQLite 数据库。</span></div></div><div class="restore-warning"><i>!</i><span><strong>恢复前会自动保存当前状态</strong>成功后可在 data/backups 中找到“恢复前快照”。</span></div><div class="modal-actions"><button type="button" class="small-btn" onclick="closeModal()">取消</button><button id="restoreSubmit" type="submit" class="primary" disabled>确认并恢复</button></div></form>`);let inspected=false;$('#backupRestoreFile').onchange=async e=>{const file=e.target.files[0],box=$('#backupInspection'),button=$('#restoreSubmit');inspected=false;button.disabled=true;if(!file)return;box.className='backup-inspection checking';box.innerHTML='<i>↻</i><div><strong>正在校验备份包…</strong><span>检查路径、文件完整性和备份清单。</span></div>';const form=new FormData();form.append('file',file);try{const info=(await api('/api/backup/inspect',{method:'POST',body:form})).data;inspected=true;button.disabled=false;const app=info.manifest?.app||{};box.className='backup-inspection valid';box.innerHTML=`<i>✓</i><div><strong>备份校验通过 · ${esc(app.name||'包裹智检')}</strong><span>${esc(info.manifest?.created_at||'未记录时间')} · ${info.file_count} 个文件 · ${formatBytes(info.uncompressed_bytes)} · ${esc(app.version||'未知版本')}</span></div>`}catch(error){box.className='backup-inspection invalid';box.innerHTML=`<i>!</i><div><strong>备份校验失败</strong><span>${esc(error.message)}</span></div>`}};$('#backupRestoreForm').onsubmit=async e=>{e.preventDefault();const file=$('#backupRestoreFile').files[0],button=$('#restoreSubmit');if(!inspected||!file)return;if(!confirm('确定恢复该备份吗？\n\n当前数据会先自动备份，然后替换为选中的备份状态。'))return;button.disabled=true;button.textContent='正在安全恢复…';const form=new FormData();form.append('file',file);form.append('confirmation','RESTORE');try{const result=(await api('/api/backup/restore',{method:'POST',body:form})).data;closeModal();await refreshBusiness();await refreshRecords();await render();toast(`备份已恢复，恢复前快照：${result.safety_backup}`)}catch(error){toast(error.message,'error');button.disabled=false;button.textContent='确认并恢复'}}};
const chartObserver=new MutationObserver(()=>{const ring=document.querySelector('.donut');if(!ring)return;for(const name of ['--l1','--l2']){const value=ring.style.getPropertyValue(name);if(value&&!value.includes('%'))ring.style.setProperty(name,`${value}%`)}});
chartObserver.observe(content,{childList:true,subtree:true});

/* Frontend R1 — category-aware decision support, anomaly guidance and review quality gate.
   This layer only reads existing API data. It never changes model inference or backend storage. */
state.productCategory=sessionStorage.getItem('inspectionProductCategory')||'general';
const productProfiles={
  general:{label:'日用百货',focus:'检查包装结构与商品外观'},
  electronics:{label:'数码家电',focus:'开箱检查功能、屏幕与内部缓冲'},
  fragile:{label:'易碎品',focus:'隔离后检查裂纹、碎裂和缓冲材料'},
  food:{label:'食品饮料',focus:'检查密封、渗漏、受潮与食用安全'},
  apparel:{label:'服饰鞋包',focus:'检查污染、受潮和外观变形'}
};
const levelActions={
  L1:{label:'低风险参考',action:'保留外包装影像，完成外观确认后继续流转。'},
  L2:{label:'需要核验',action:'暂停自动流转，建议开箱核验并由工作人员确认。'},
  L3:{label:'高风险处置',action:'隔离包裹并优先人工复核，保留取证材料后再决定后续处置。'}
};
function selectedProduct(){return productProfiles[state.productCategory]||productProfiles.general}
function responsibilityHint(type=''){
  if(/浸|湿|水/.test(type))return '疑似受潮或液体接触，需结合仓储环境和物流节点核验。';
  if(/撕|破|洞/.test(type))return '疑似外力刮碰、穿刺或包装防护不足，需结合包裹交接影像核验。';
  if(/形|挤|压|凹/.test(type))return '疑似运输挤压或堆码压力，需结合箱体受力方向和物流节点核验。';
  return '当前视觉证据不足，责任归属应由工作人员结合物流信息确认。'
}
function decisionSupport(d){
  const decision=d?.decision||{},level=levelActions[decision.damage_level]||levelActions.L2,product=selectedProduct();
  return {product,level,handling:`${level.action}${product.focus}。`,responsibility:responsibilityHint(decision.damage_type)}
}
function anomalyFlags(d){
  const detections=d?.detections||[],flags=[],top=detections.reduce((m,x)=>Math.max(m,Number(x.confidence)||0),0);
  const levels=new Set(detections.map(x=>x.level).filter(Boolean)),types=new Set(detections.map(x=>x.damage_type).filter(Boolean));
  if(!detections.length)flags.push({tone:'danger',title:'未检出不等于确认完好',copy:'当前模型没有找到已定义破损区域，建议检查图片质量并保留人工复核入口。'});
  if(detections.length&&top<0.35)flags.push({tone:'warning',title:'低置信度结果',copy:`最高置信度仅 ${Math.round(top*100)}%，不建议直接形成最终定损结论。`});
  if(levels.size>1)flags.push({tone:'warning',title:'损伤等级存在分歧',copy:'同一图片出现多个等级，前端已提示人工确认最终等级。'});
  if(types.size>1)flags.push({tone:'info',title:'检测到复合破损',copy:'图片包含多种破损类型，建议逐区域核对后再确定总体处置。'});
  if(Number(d?.inference_ms||0)>5000)flags.push({tone:'info',title:'本次推理耗时较长',copy:'结果已经完成，但建议记录设备环境用于后续性能评估。'});
  if(!flags.length)flags.push({tone:'safe',title:'结果结构完整',copy:'已获得破损区域、类型、等级和置信度；最终结论仍以人工复核为准。'});
  return flags
}
function decisionSupportMarkup(d){
  const support=decisionSupport(d),flags=anomalyFlags(d);
  return `<section class="decision-support"><div class="decision-support-head"><div><span class="step-kicker">BUSINESS DECISION SUPPORT</span><h3>定损辅助建议</h3></div><span class="frontend-demo-chip">前端规则演示</span></div><div class="decision-support-grid"><div><small>商品类目</small><strong>${esc(support.product.label)}</strong><span>${esc(support.product.focus)}</span></div><div><small>${esc(support.level.label)}</small><strong>${esc(support.handling)}</strong></div><div><small>责任线索 · 待人工确认</small><strong>${esc(support.responsibility)}</strong></div></div><div class="anomaly-stack">${flags.map(flag=>`<article class="anomaly-item ${flag.tone}"><i>${flag.tone==='safe'?'✓':'!'}</i><div><strong>${esc(flag.title)}</strong><span>${esc(flag.copy)}</span></div></article>`).join('')}</div><p class="decision-disclaimer">以上为演示规则生成的辅助建议，不等同于正式赔付或责任认定。</p></section>`
}
const baseResultMarkupR1=resultMarkup;
resultMarkup=function(d){return baseResultMarkupR1(d)+decisionSupportMarkup(d)};

function validateImageSelection(files){
  const list=Array.from(files||[]),allowed=new Set(['image/jpeg','image/png','image/webp']);
  if(!list.length)return '请选择需要检测的图片。';
  if(list.length>10)return '每批最多选择 10 张图片。';
  if(list.some(file=>!allowed.has(file.type)))return '仅支持 JPG、PNG、WEBP 图片。';
  if(list.some(file=>file.size===0))return '检测到空文件，请重新选择图片。';
  if(list.some(file=>file.size>20*1024*1024))return '单张图片不能超过 20 MB。';
  return ''
}
function installUploadGuard(){
  const input=$('#file'),drop=$('#dropzone'),status=$('#frontendValidation');if(!input||!drop)return;
  const inspect=(files,event)=>{const error=validateImageSelection(files);if(error){event.preventDefault();event.stopImmediatePropagation();input.value='';status.className='frontend-validation error';status.innerHTML=`<i>!</i><span>${esc(error)}</span>`;toast(error,'error');return false}const size=Array.from(files).reduce((sum,file)=>sum+file.size,0);status.className='frontend-validation ok';status.innerHTML=`<i>✓</i><span>前端检查通过：${files.length} 张图片，共 ${(size/1024/1024).toFixed(2)} MB</span>`;return true};
  input.addEventListener('change',event=>inspect(event.target.files,event),true);
  drop.addEventListener('drop',event=>inspect(event.dataTransfer?.files,event),true)
}
const baseRenderDetectR1=renderDetect;
renderDetect=function(){
  baseRenderDetectR1();
  const upload=$('.upload-card'),drop=$('#dropzone');if(!upload||!drop)return;
  const options=Object.entries(productProfiles).map(([key,item])=>`<option value="${key}" ${key===state.productCategory?'selected':''}>${esc(item.label)}</option>`).join('');
  drop.insertAdjacentHTML('beforebegin',`<section class="inspection-context"><div><span class="context-index">业务上下文</span><strong>选择商品类目</strong><small>不改变模型推理，仅用于生成前端定损辅助建议。</small></div><label><span>商品类目</span><select id="productCategory">${options}</select></label></section><div id="frontendValidation" class="frontend-validation"><i>i</i><span>选择图片后将先检查格式、数量与文件大小。</span></div>`);
  $('#productCategory').onchange=event=>{state.productCategory=event.target.value;sessionStorage.setItem('inspectionProductCategory',state.productCategory);if(state.result)$('#result').innerHTML=resultMarkup(state.result);toast(`已切换为${selectedProduct().label}定损规则`)};
  installUploadGuard()
};

const baseRenderSamplesR1=renderSamples;
renderSamples=function(){
  baseRenderSamplesR1();
  const exportBar=$('.feedback-export-bar');if(!exportBar)return;
  exportBar.insertAdjacentHTML('afterend',`<section class="feedback-trust-strip"><div><i>01</i><span><strong>AI 生成候选框</strong><small>保留原始预测，不冒充人工真值</small></span></div><div><i>02</i><span><strong>人工确认业务结论</strong><small>核对类型、等级和复核意见</small></span></div><div><i>03</i><span><strong>标注员复核后训练</strong><small>导出包仍需检查边界框</small></span></div></section>`)
};

const baseOpenReviewR1=window.openReview;
window.openReview=async id=>{
  await baseOpenReviewR1(id);
  const form=$('#reviewForm'),actions=form?.querySelector('.modal-actions');if(!form||!actions)return;
  actions.insertAdjacentHTML('beforebegin',`<section class="review-quality-gate"><div class="quality-head"><div><strong>提交前质量确认</strong><span>前端检查项，不改变模型原始结果</span></div><span class="frontend-demo-chip">必须确认</span></div><label><input id="reviewImageChecked" type="checkbox"> 已对照原图与AI标注图</label><label><input id="reviewRiskChecked" type="checkbox"> 已确认等级和处置意见符合当前证据</label><p>当前版本尚未提供检测框拖拽编辑；导出的AI框仍需标注员再次检查。</p></section>`);
  form.addEventListener('submit',event=>{if($('#reviewImageChecked').checked&&$('#reviewRiskChecked').checked)return;event.preventDefault();event.stopImmediatePropagation();toast('请先完成两项复核质量确认','error')},true)
};

/* Frontend R2 — visual region inspection. Audit marks stay in this browser session only. */
try{state.regionAudit=JSON.parse(sessionStorage.getItem('regionAudit')||'{}')}catch{state.regionAudit={}}
const auditLabels={valid:'框选有效',suspect:'需要复查',redraw:'建议重画'};
function auditKey(result,index){return `${result?.id||'current'}:${index}`}
function persistRegionAudit(){sessionStorage.setItem('regionAudit',JSON.stringify(state.regionAudit||{}))}
function auditSummary(result){
  const detections=result?.detections||[],summary={valid:0,suspect:0,redraw:0,pending:0};
  detections.forEach((_,index)=>{const status=state.regionAudit?.[auditKey(result,index)];if(summary[status]!==undefined)summary[status]+=1;else summary.pending+=1});
  return summary
}
function regionInspectorMarkup(result){
  const detections=result?.detections||[],summary=auditSummary(result),image=result?.original_image_url||`/uploads/${esc(result?.original_image||'')}`;
  return `<div class="modal-head"><div><span class="step-kicker">REGION QUALITY CHECK</span><h2>检测区域人工核验</h2><p>任务 #${String(result?.id||0).padStart(4,'0')} · 核验标记仅保存在当前前端会话</p></div><button class="modal-close" onclick="closeModal()">×</button></div><section class="region-audit-summary"><div><small>识别区域</small><strong>${detections.length}</strong></div><div><small>框选有效</small><strong>${summary.valid}</strong></div><div><small>需要复查</small><strong>${summary.suspect}</strong></div><div><small>建议重画</small><strong>${summary.redraw}</strong></div></section><div class="region-inspector-layout"><figure class="region-canvas"><div class="region-image-stage"><img src="${image}" alt="包裹原图">${detections.map((item,index)=>{const status=state.regionAudit?.[auditKey(result,index)]||'pending',bbox=(item.bbox||[]).map(Number).join(',');return `<button class="region-box ${status}" data-bbox="${bbox}" onclick="focusRegion(${index})" aria-label="核验区域 ${index+1}"><span>${index+1}</span></button>`}).join('')}</div><figcaption>点击图片中的框，可定位右侧对应检测区域。</figcaption></figure><section class="region-audit-list">${detections.length?detections.map((item,index)=>{const status=state.regionAudit?.[auditKey(result,index)]||'pending';return `<article class="region-audit-row ${status}" data-region-index="${index}"><button class="region-row-main" onclick="focusRegion(${index})"><i>${index+1}</i><span><strong>${esc(item.damage_type)} · ${esc(item.level)}</strong><small>置信度 ${Math.round(Number(item.confidence||0)*100)}% · 面积占比 ${(Number(item.area_ratio||0)*100).toFixed(1)}%</small></span><b>${esc(auditLabels[status]||'待核验')}</b></button><div class="region-audit-actions"><button class="${status==='valid'?'active':''}" onclick="setRegionAudit(${index},'valid')">有效</button><button class="${status==='suspect'?'active':''}" onclick="setRegionAudit(${index},'suspect')">存疑</button><button class="${status==='redraw'?'active':''}" onclick="setRegionAudit(${index},'redraw')">重画</button></div></article>`}).join(''):'<div class="region-audit-empty"><i>!</i><strong>当前没有可核验的检测框</strong><span>未检出不代表确认完好，建议转入人工复核。</span></div>'}</section></div><div class="region-audit-note"><i>i</i><span><strong>前端核验不会修改模型结果</strong>当前标记用于演示质量校验流程；正式回流训练前仍需在标注工具中保存修正后的边界框。</span></div><div class="modal-actions"><button class="small-btn" onclick="closeModal()">稍后处理</button><button class="primary" onclick="finishRegionAudit()">完成当前核验</button></div>`
}
function positionInspectorBoxes(){
  const stage=$('.region-image-stage'),image=stage?.querySelector('img');if(!stage||!image||!image.naturalWidth||!image.naturalHeight)return;
  const stageWidth=stage.clientWidth,stageHeight=stage.clientHeight,scale=Math.min(stageWidth/image.naturalWidth,stageHeight/image.naturalHeight),renderWidth=image.naturalWidth*scale,renderHeight=image.naturalHeight*scale,offsetX=(stageWidth-renderWidth)/2,offsetY=(stageHeight-renderHeight)/2;
  stage.querySelectorAll('.region-box').forEach(box=>{const [x1,y1,x2,y2]=(box.dataset.bbox||'').split(',').map(Number);if(![x1,y1,x2,y2].every(Number.isFinite)){box.hidden=true;return}box.hidden=false;box.style.left=`${offsetX+Math.max(0,x1)*scale}px`;box.style.top=`${offsetY+Math.max(0,y1)*scale}px`;box.style.width=`${Math.max((x2-x1)*scale,22)}px`;box.style.height=`${Math.max((y2-y1)*scale,22)}px`})
}
function showRegionInspector(index=0){
  modal(regionInspectorMarkup(state.result));
  const image=$('.region-image-stage img'),stage=$('.region-image-stage'),layout=()=>{positionInspectorBoxes();focusRegion(index)};
  if(image?.complete)requestAnimationFrame(layout);else if(image)image.onload=layout;
  state.regionResizeObserver?.disconnect();
  if(stage&&'ResizeObserver' in window){state.regionResizeObserver=new ResizeObserver(positionInspectorBoxes);state.regionResizeObserver.observe(stage)}
}
window.openRegionInspector=()=>{if(!state.result)return toast('请先完成一次图片检测','error');showRegionInspector(state.activeRegionIndex||0)};
window.focusRegion=index=>{state.activeRegionIndex=index;document.querySelectorAll('.region-box,.region-audit-row').forEach(node=>node.classList.remove('focused'));document.querySelector(`.region-box:nth-of-type(${index+1})`)?.classList.add('focused');const row=document.querySelector(`[data-region-index="${index}"]`);row?.classList.add('focused');row?.scrollIntoView({block:'nearest',behavior:'smooth'})};
window.setRegionAudit=(index,status)=>{if(!state.result)return;state.regionAudit[auditKey(state.result,index)]=status;persistRegionAudit();showRegionInspector(index);toast(`区域 ${index+1} 已标记为“${auditLabels[status]}”`)};
window.finishRegionAudit=()=>{if(!state.result)return closeModal();const summary=auditSummary(state.result),unfinished=summary.pending;if(unfinished)return toast(`还有 ${unfinished} 个区域尚未核验`,'error');closeModal();$('#result').innerHTML=resultMarkup(state.result);toast('当前检测区域已完成前端核验')};
const baseDecisionSupportMarkupR2=decisionSupportMarkup;
decisionSupportMarkup=function(result){
  const base=baseDecisionSupportMarkupR2(result),detections=result?.detections||[],summary=auditSummary(result),done=summary.pending===0&&detections.length>0;
  const entry=`<div class="region-inspection-entry"><div><i>${done?'✓':'⌖'}</i><span><strong>${done?'区域核验已完成':'核验检测区域'}</strong><small>${detections.length?`${detections.length-summary.pending}/${detections.length} 个区域已确认`:'当前无检测框，建议人工检查原图'}</small></span></div><button type="button" onclick="openRegionInspector()">${done?'查看核验结果':'开始核验'} →</button></div>`;
  return base.replace('<p class="decision-disclaimer">',`${entry}<p class="decision-disclaimer">`)
};
boot();
